  /**
   * (Optional) The ListID or FullName of the Sales Rep. (SalesRepRef, Flattened-ID Pattern)
   */
  salesRepId?: string | null;
  /**
   * (Optional) Freight on Board term. (STRTYPE)
   */
  fob?: string | null;
  /**
   * (Optional) The ListID or FullName of the sales tax item that applies to the entire Estimate. Cannot be cleared. (ItemSalesTaxRef, Flattened-ID Pattern)
   */
  itemSalesTaxId?: string | null;
